<#
  Grimoire - icônes des fichiers sous Windows
  -------------------------------------------
  Chrome et Edge enregistrent Grimoire pour ouvrir les .docx, .xlsx, .csv et .pdf,
  mais ne donnent aucune icône de fichier à Windows : l'Explorateur affiche alors
  des pages blanches, toutes identiques.

  Ce script, à lancer une fois (clic droit > Exécuter avec PowerShell) :
    1. copie quatre icônes (DOC, XLS, CSV, PDF) dans %LOCALAPPDATA%\Grimoire\icones ;
    2. crée quatre types de fichiers « Grimoire · Document / Classeur / CSV / PDF »
       qui ouvrent Grimoire exactement comme le fait Chrome ou Edge, avec leur icône ;
    3. les propose dans « Ouvrir avec » pour les extensions concernées.

  Ensuite, une fois par type : clic droit sur un fichier > Ouvrir avec >
  Choisir une autre application > « Grimoire · Document » (ou Classeur…) >
  cocher « Toujours utiliser cette application » > OK.

  Aucun droit administrateur : tout est écrit dans le profil de l'utilisateur
  (HKCU). Pour tout retirer : relancer le script avec le paramètre -Retirer.
#>
param([switch]$Retirer)

$ErrorActionPreference = 'Stop'
$marque  = 'Grimoire-icones'
$dossier = Join-Path $env:LOCALAPPDATA 'Grimoire\icones'
$hkcu    = [Microsoft.Win32.Registry]::CurrentUser
$classes = 'Software\Classes'

$types = @(
  @{ Id = 'Grimoire.Document'; Appli = 'Grimoire · Document'; Libelle = 'Document Grimoire';    Icone = 'document'; Ext = @('.docx') },
  @{ Id = 'Grimoire.Classeur'; Appli = 'Grimoire · Classeur'; Libelle = 'Classeur Grimoire';    Icone = 'classeur'; Ext = @('.xlsx', '.xlsm') },
  @{ Id = 'Grimoire.CSV';      Appli = 'Grimoire · CSV';      Libelle = 'Fichier CSV Grimoire'; Icone = 'csv';      Ext = @('.csv') },
  @{ Id = 'Grimoire.PDF';      Appli = 'Grimoire · PDF';      Libelle = 'PDF Grimoire';         Icone = 'pdf';      Ext = @('.pdf') }
)

$icones = @{
  'document' = ''
  'classeur' = ''
  'csv' = ''
  'pdf' = ''
}

function Rafraichir-Explorateur {
  if (-not ('GrimoireNatif.Shell' -as [type])) {
    Add-Type -Name Shell -Namespace GrimoireNatif -MemberDefinition @'
[System.Runtime.InteropServices.DllImport("shell32.dll")]
public static extern void SHChangeNotify(int eventId, uint flags, System.IntPtr item1, System.IntPtr item2);
'@
  }
  [GrimoireNatif.Shell]::SHChangeNotify(0x08000000, 0, [IntPtr]::Zero, [IntPtr]::Zero)
}

function Ouvrir-Cle([string]$chemin) { return $hkcu.OpenSubKey($chemin) }

function Est-ProgIdGrimoire([string]$id) {
  if ([string]::IsNullOrEmpty($id) -or $id -like 'Grimoire.*') { return $false }
  $app = Ouvrir-Cle "$classes\$id\Application"
  $cmd = Ouvrir-Cle "$classes\$id\shell\open\command"
  if (-not $app -or -not $cmd) { return $false }
  $nom = [string]$app.GetValue('ApplicationName')
  return ($nom -like 'Grimoire*')
}

# Trouve le type de fichier créé par Chrome / Edge pour l'appli Grimoire installée
function Trouver-ProgIdNavigateur {
  $candidats = New-Object System.Collections.Generic.List[string]
  foreach ($t in $types) {
    foreach ($ext in $t.Ext) {
      $choix = Ouvrir-Cle "Software\Microsoft\Windows\CurrentVersion\Explorer\FileExts\$ext\UserChoice"
      if ($choix) { $candidats.Add([string]$choix.GetValue('ProgId')) }
      $owp = Ouvrir-Cle "$classes\$ext\OpenWithProgids"
      if ($owp) { foreach ($n in $owp.GetValueNames()) { $candidats.Add($n) } }
    }
  }
  foreach ($c in $candidats) { if (Est-ProgIdGrimoire $c) { return $c } }
  # Dernier recours : parcourir tous les types de fichiers de l'utilisateur
  $racine = Ouvrir-Cle $classes
  foreach ($n in $racine.GetSubKeyNames()) {
    if ($n.StartsWith('.')) { continue }
    if (Est-ProgIdGrimoire $n) { return $n }
  }
  return $null
}

function Copier-Valeurs($source, $cible) {
  foreach ($n in $source.GetValueNames()) {
    $cible.SetValue($n, $source.GetValue($n, $null, 'DoNotExpandEnvironmentNames'), $source.GetValueKind($n))
  }
}

function Retirer-Tout {
  foreach ($t in $types) {
    $cle = Ouvrir-Cle "$classes\$($t.Id)"
    if ($cle -and [string]$cle.GetValue('CreePar') -eq $marque) {
      $hkcu.DeleteSubKeyTree("$classes\$($t.Id)", $false)
      Write-Host "  - type $($t.Id) retiré"
    }
    foreach ($ext in $t.Ext) {
      $owp = $hkcu.OpenSubKey("$classes\$ext\OpenWithProgids", $true)
      if ($owp -and ($owp.GetValueNames() -contains $t.Id)) { $owp.DeleteValue($t.Id) }
    }
  }
  if (Test-Path -LiteralPath $dossier) { Remove-Item -LiteralPath $dossier -Recurse -Force }
}

Write-Host ''
Write-Host '  Grimoire - icônes des fichiers sous Windows' -ForegroundColor Yellow
Write-Host ''

try {
  if ($Retirer) {
    Retirer-Tout
    Rafraichir-Explorateur
    Write-Host ''
    Write-Host '  C''est retiré. Choisis de nouveau l''appli par défaut si besoin (Ouvrir avec).' -ForegroundColor Green
  }
  else {
    $source = Trouver-ProgIdNavigateur
    if (-not $source) {
      Write-Host '  Grimoire n''est pas trouvé comme appli installée sur ce PC.' -ForegroundColor Red
      Write-Host '  Installe-le d''abord depuis Chrome ou Edge (icône d''installation dans la barre d''adresse),'
      Write-Host '  puis relance ce script.'
    }
    else {
      Write-Host "  Appli Grimoire trouvée (type $source)."

      New-Item -ItemType Directory -Path $dossier -Force | Out-Null
      foreach ($nom in $icones.Keys) {
        [IO.File]::WriteAllBytes((Join-Path $dossier "$nom.ico"), [Convert]::FromBase64String($icones[$nom]))
      }

      $srcApp = Ouvrir-Cle "$classes\$source\Application"
      $srcCmd = Ouvrir-Cle "$classes\$source\shell\open\command"

      foreach ($t in $types) {
        $base = "$classes\$($t.Id)"
        $hkcu.DeleteSubKeyTree($base, $false)
        $cle = $hkcu.CreateSubKey($base)
        $cle.SetValue('', $t.Libelle)
        $cle.SetValue('FriendlyTypeName', $t.Libelle)
        $cle.SetValue('CreePar', $marque)
        $cle.SetValue('Source', $source)

        $ico = $hkcu.CreateSubKey("$base\DefaultIcon")
        $ico.SetValue('', (Join-Path $dossier "$($t.Icone).ico"))

        $app = $hkcu.CreateSubKey("$base\Application")
        Copier-Valeurs $srcApp $app
        $app.SetValue('ApplicationName', $t.Appli)

        $cmd = $hkcu.CreateSubKey("$base\shell\open\command")
        Copier-Valeurs $srcCmd $cmd

        foreach ($ext in $t.Ext) {
          $owp = $hkcu.CreateSubKey("$classes\$ext\OpenWithProgids")
          $owp.SetValue($t.Id, '')
        }
        Write-Host "  + $($t.Appli)  ($($t.Ext -join ', '))"
      }

      Rafraichir-Explorateur
      Write-Host ''
      Write-Host '  Terminé. Dernière étape, une fois par type de fichier :' -ForegroundColor Green
      Write-Host '    clic droit sur un .docx > Ouvrir avec > Choisir une autre application'
      Write-Host '    > « Grimoire · Document » > Toujours (ou cocher « Toujours utiliser… »).'
      Write-Host '    Pareil avec un .xlsx > « Grimoire · Classeur » (et .csv / .pdf si tu veux).'
      Write-Host ''
      Write-Host '  Si l''appli Grimoire est désinstallée puis réinstallée, relance ce script.'
    }
  }
}
catch {
  Write-Host ''
  Write-Host "  Erreur : $($_.Exception.Message)" -ForegroundColor Red
}

Write-Host ''
Read-Host '  Appuie sur Entrée pour fermer' | Out-Null
